// Package embedded ships the catalog's conversion specs inside standalone
// binaries (the CLI's offline upgrade-manifest needs every authored bridge
// with no checkout and no network).
//
// The AUTHORED specs live beside each kind's protos
// (catalog/<provider>/<kind>/conversions/*.yaml) -- that
// co-location is the contract. Go embeds cannot cross Bazel package
// boundaries, so this package carries a generated byte-for-byte mirror
// instead (the same committed-artifact pattern protodocs uses):
//
//	make generate-conversion-registry
//
// regenerates the mirror, and the drift gate in pkg/conversion fails CI
// whenever mirror and sources disagree.
package embedded

import (
	"embed"
	"io/fs"
)

//go:embed all:specs
var embeddedSpecs embed.FS

// SpecsFS returns the embedded specs rooted like the provider base, so
// conversion.SpecFiles and friends work identically on a checkout and on
// the embed.
func SpecsFS() (fs.FS, error) {
	return fs.Sub(embeddedSpecs, "specs")
}
